using System;using System.Reflection;using NUnit.Framework;using Rootborn.Game.Localization;using Rootborn.Game.Common;using Rootborn.Game.WorldState;using Rootborn.UI.WorldState;using Rootborn.UI.Encyclopedia;using Rootborn.UI.StudentLife;using UnityEngine;using UnityEngine.UI;using UnityEditor.SceneManagement;
namespace Rootborn.Tests.EditMode.UI {public sealed class UrbanUtilityMenuPresentationTests {
GameObject canvas;UnityEngine.SceneManagement.Scene scene;string language;
[SetUp]public void Setup(){language=GameText.Language;GameText.Language="ko";scene=EditorSceneManager.NewPreviewScene();canvas=new GameObject("UtilityCanvas",typeof(RectTransform),typeof(Canvas));UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(canvas,scene);((RectTransform)canvas.transform).sizeDelta=new Vector2(1920,1080);}
[TearDown]public void Cleanup(){if(canvas!=null)UnityEngine.Object.DestroyImmediate(canvas);if(scene.IsValid())EditorSceneManager.ClosePreviewScene(scene);GameText.Language=language;}
GameObject Child(string name){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(canvas.transform,false);return g;}
WorldStateLogPanel World(){var panel=Child("WorldPanel").AddComponent<WorldStateLogPanel>();typeof(WorldStateLogRuntimeInstaller).GetMethod("EnsureButton",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,canvas.GetComponent<Canvas>(),panel,(Func<WorldStateSummaryModel[]>)(()=>Array.Empty<WorldStateSummaryModel>()),null});return panel;}
[Test]public void WorldLogButtonIsBelowCareerAndInterestControlsWithReadableKoreanFont(){World();var b=(RectTransform)canvas.transform.Find("WorldStateLogButton");Assert.That(b.anchoredPosition.y+b.rect.height,Is.LessThanOrEqualTo(-152f-12f),"Top-left utility must leave interest controls through208px clear");Assert.That(b.anchoredPosition.y,Is.LessThanOrEqualTo(-220f));var label=b.GetComponentInChildren<Text>();Assert.That(label.text,Is.EqualTo("\uB9C8\uC744 \uAE30\uB85D"));Assert.That(label.font,Is.SameAs(typeof(WorldStateLogPanel).Assembly.GetType("Rootborn.UI.StudentLife.LifeUiFont").GetProperty("Shared").GetValue(null)));}
[Test]public void EncyclopediaButtonUsesKoreanCaptionAndSharedFont(){var panel=Child("EncyclopediaPanel").AddComponent<EncyclopediaPanel>();typeof(EncyclopediaRuntimeInstaller).GetMethod("EnsureButton",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{canvas.transform,panel});var b=canvas.transform.Find("EncyclopediaButton");var label=b.GetComponentInChildren<Text>();Assert.That(label.text,Is.EqualTo("\uB3C4\uAC10"));Assert.That(label.font,Is.SameAs(typeof(WorldStateLogPanel).Assembly.GetType("Rootborn.UI.StudentLife.LifeUiFont").GetProperty("Shared").GetValue(null)));Assert.That(label.raycastTarget,Is.False);}
[Test]public void EncyclopediaTitleCloseAndColumnsRemainInsidePanel(){var p=Child("EncyclopediaPanel").AddComponent<EncyclopediaPanel>();((RectTransform)p.transform).sizeDelta=new Vector2(820,560);p.Show();var root=(RectTransform)p.transform;foreach(string name in new[]{"EncyclopediaTitle","CloseButton","CategoryTabs","EntryRows","EntryDetail"}){var r=p.transform.Find(name) as RectTransform;Assert.That(r,Is.Not.Null,name);var corners=new Vector3[4];r.GetWorldCorners(corners);foreach(var c in corners){var local=root.InverseTransformPoint(c);Assert.That(root.rect.Contains(new Vector2(local.x,local.y)),Is.True,name+" outside panel at"+local);}}p.Hide();Assert.That(UiGameplayInputLock.IsBlocked,Is.False);}
[Test]public void WorldLogHasActualCloseControlAndReleasesGameplayLock(){var p=World();p.gameObject.SetActive(false);p.Show(Array.Empty<WorldStateSummaryModel>());Assert.That(p.gameObject.activeSelf,Is.True,"Return-cleaned host must reactivate when opened through its menu");Assert.That(UiGameplayInputLock.IsBlocked,Is.True);var close=p.transform.Find("WorldStateLogRoot/CloseButton");Assert.That(close,Is.Not.Null,"Exposing the menu needs a clickable way to return to gameplay");close.GetComponent<Button>().onClick.Invoke();Assert.That(p.transform.Find("WorldStateLogRoot").gameObject.activeSelf,Is.False);Assert.That(UiGameplayInputLock.IsBlocked,Is.False);}
}}
